import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int diff;
        int index;
        Edge(int diff, int index) {
            this.diff = diff;
            this.index = index;
        }
    }

    static class FastScanner {
        private final InputStream in;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() throws IOException {
            int c = in.read();
            while (isSpace(c)) {
                if (c == -1) throw new InputMismatchException();
                c = in.read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = in.read();
            }
            int res = 0;
            while (!isSpace(c)) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = in.read();
            }
            return res * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int k = fs.nextInt();
        int[] a = new int[n];
        int[] odd = new int[n];
        int balance = 0;
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
            balance += (a[i] & 1) == 0 ? 1 : -1;
            odd[i] = balance;
        }

        PriorityQueue<Edge> pq = new PriorityQueue<>((e1, e2) -> {
            int cmp = e1.diff - e2.diff;
            if (cmp != 0) return cmp;
            return e1.index - e2.index;
        });

        for (int i = 0; i + 1 < n; i++) {
            pq.add(new Edge(Math.abs(a[i + 1] - a[i]), i));
        }

        int ans = 0;
        while (!pq.isEmpty() && pq.peek().diff <= k) {
            Edge e = pq.poll();
            if (odd[e.index] == 0) {
                int nk = k - e.diff;
                if (nk >= 0) {
                    ans++;
                    k = nk;
                }
            }
        }
        System.out.println(ans);
    }
}
